      // Time & Attendance methods
      async getStaffTimeAndAttendance(dateFrom, dateTo) {
        const allStaff = await this.getAllStaff();
        const result = [];
        for (const staffMember of allStaff) {
          const whereConditions = [eq(staffSessions.staffId, staffMember.id)];
          if (dateFrom) {
            whereConditions.push(gte(staffSessions.checkInTime, dateFrom));
          }
          if (dateTo) {
            const endOfDay = new Date(dateTo);
            endOfDay.setHours(23, 59, 59, 999);
            whereConditions.push(lte(staffSessions.checkInTime, endOfDay));
          }
          const sessions = await db.select().from(staffSessions).where(and(...whereConditions)).orderBy(desc(staffSessions.checkInTime));
          const processedSessions = sessions.map((session2) => {
            let hoursWorked = 0;
            if (session2.checkOutTime) {
              hoursWorked = (session2.checkOutTime.getTime() - session2.checkInTime.getTime()) / (1e3 * 60 * 60);
            } else {
              hoursWorked = ((/* @__PURE__ */ new Date()).getTime() - session2.checkInTime.getTime()) / (1e3 * 60 * 60);
            }
            return {
              checkInTime: session2.checkInTime,
              checkOutTime: session2.checkOutTime,
              hoursWorked: Math.max(0, hoursWorked),
              // Ensure no negative hours
              isManual: session2.isManual
            };
          });
          const totalHours = processedSessions.reduce((sum, session2) => sum + session2.hoursWorked, 0);
          result.push({
            staffId: staffMember.id,
            staffName: `${staffMember.firstName} ${staffMember.lastName}`,
            department: staffMember.department,
            sessions: processedSessions,
            totalHours
          });
        }
        return result;
      }
