      async getStaffTimeAndAttendance(context, dateFrom, dateTo) {
        const db2 = await customerDbService.getCustomerDatabase(context.customerId);
        const fromDate = dateFrom || new Date(Date.now() - 30 * 24 * 60 * 60 * 1e3);
        const toDate = dateTo || /* @__PURE__ */ new Date();
        const staff4 = await db2.select().from(staff3).where(eq4(staff3.isActive, true));
        const sessionHistory = await db2.select().from(staffSessions2).where(and2(
          gte2(staffSessions2.checkInTime, fromDate),
          lte2(staffSessions2.checkInTime, toDate)
        )).orderBy(asc2(staffSessions2.checkInTime));
        const sessionsByStaff = /* @__PURE__ */ new Map();
        sessionHistory.forEach((record) => {
          const staffRecords = sessionsByStaff.get(record.staffId) || [];
          staffRecords.push(record);
          sessionsByStaff.set(record.staffId, staffRecords);
        });
        return staff4.map((staffMember) => {
          const staffSessions3 = sessionsByStaff.get(staffMember.id) || [];
          const sessions = staffSessions3.map((record) => {
            const hoursWorked = record.checkOutTime ? (record.checkOutTime.getTime() - record.checkInTime.getTime()) / (1e3 * 60 * 60) : (Date.now() - record.checkInTime.getTime()) / (1e3 * 60 * 60);
            return {
              checkInTime: record.checkInTime,
              checkOutTime: record.checkOutTime,
              hoursWorked,
              isManual: record.isManual
            };
          });
          const totalHours = sessions.reduce((sum, session2) => sum + session2.hoursWorked, 0);
          return {
            staffId: staffMember.id,
            staffName: `${staffMember.firstName} ${staffMember.lastName}`,
            department: staffMember.department,
            sessions,
            totalHours
          };
        }).filter((record) => record.sessions.length > 0).sort((a, b) => a.staffName.localeCompare(b.staffName));
      }
