      // Helper function to get logo for email as base64 data URL
      async getLogoForEmail(settings) {
        try {
          if (!settings?.logoUrl) {
            return null;
          }
          const logoPath = settings.logoUrl.startsWith("/objects") ? settings.logoUrl : `/objects${settings.logoUrl}`;
          const logoUrl = `http://localhost:5000${logoPath}`;
          console.log("Fetching logo from:", logoUrl);
          const response = await fetch(logoUrl);
          if (!response.ok) {
            console.log("Failed to fetch logo:", response.status);
            return null;
          }
          const buffer = await response.arrayBuffer();
          const base64 = Buffer.from(buffer).toString("base64");
          const contentType = response.headers.get("content-type") || "image/png";
          return `data:${contentType};base64,${base64}`;
        } catch (error) {
          console.error("Error converting logo to base64:", error);
          return null;
        }
      }
