      async sendMeetingReminder(booking, room, organizer, staffAttendees = [], externalAttendeeEmails = []) {
        const subject = `Reminder: ${booking.title} starts in 15 minutes`;
        const html = `
      <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
        <div style="background: linear-gradient(135deg, #ff9800 0%, #f57c00 100%); color: white; padding: 20px; text-align: center;">
          <h1 style="margin: 0; font-size: 20px;">\u23F0 Meeting Reminder</h1>
        </div>
        
        <div style="padding: 20px; background: #fff8e1; border-left: 4px solid #ff9800;">
          <h2 style="color: #333; margin-top: 0;">${booking.title}</h2>
          <p><strong>Starting in 15 minutes</strong> at ${room.name} (${room.location})</p>
          <p>Expected attendees: ${booking.expectedAttendees} people</p>
          
          ${booking.requiresCatering ? '<p style="color: #f57c00;">\u{1F37D}\uFE0F <strong>Catering arranged</strong></p>' : ""}
          
          <div style="text-align: center; margin-top: 20px;">
            <p style="color: #666; font-size: 14px;">See you there! \u{1F44B}</p>
          </div>
        </div>
      </div>
    `;
        const text3 = `Meeting Reminder: ${booking.title}

Starting in 15 minutes at ${room.name} (${room.location})
Expected attendees: ${booking.expectedAttendees} people

${booking.requiresCatering ? "Catering arranged\n\n" : ""}See you there!`;
        const allEmails = [
          organizer.email,
          ...staffAttendees.map((staff4) => staff4.email),
          ...externalAttendeeEmails
        ].filter(Boolean);
        let success = true;
        for (const email of allEmails) {
          const emailSuccess = await this.sendEmail({ to: email, subject, html, text: text3 });
          if (!emailSuccess) success = false;
        }
        return success;
      }
