        staffId: staff4.id,
        notificationType: "emergency_alert",
        messageText: emergencyMessage,
        voiceLanguage: staff4.voiceLanguage || "en-GB",
        voiceProfile: staff4.voiceProfile || "en-GB-Standard-A",
        urgentRetry: true
