var createLogger = () => {
  const isProduction2 = process.env.NODE_ENV === "production";
  const logLevel = process.env.LOG_LEVEL || (isProduction2 ? "info" : "debug");
  const productionFormat = winston.format.combine(
    winston.format.timestamp({ format: "YYYY-MM-DD HH:mm:ss.SSS" }),
    winston.format.errors({ stack: true }),
    winston.format.json(),
    winston.format.printf((info) => {
      const { timestamp: timestamp3, level, message, ...meta } = info;
      return JSON.stringify({
        timestamp: timestamp3,
        level: level.toUpperCase(),
        message,
        service: "visigate-pro",
        environment: process.env.NODE_ENV || "development",
        version: process.env.APP_VERSION || "1.0.0",
        ...meta
      });
    })
  );
  const developmentFormat = winston.format.combine(
    winston.format.timestamp({ format: "HH:mm:ss" }),
    winston.format.errors({ stack: true }),
    winston.format.colorize(),
    winston.format.printf((info) => {
      const { timestamp: timestamp3, level, message, requestId, customerId, userId, ...meta } = info;
      const contextParts = [];
      if (requestId && typeof requestId === "string") contextParts.push(`req:${requestId.slice(-8)}`);
      if (customerId && typeof customerId === "string") contextParts.push(`customer:${customerId.slice(-8)}`);
      if (userId && typeof userId === "string") contextParts.push(`user:${userId.slice(-8)}`);
      const context = contextParts.length > 0 ? ` [${contextParts.join("|")}]` : "";
      const metaStr = Object.keys(meta).length > 0 ? ` ${JSON.stringify(meta)}` : "";
      return `${timestamp3} ${level}${context}: ${message}${metaStr}`;
    })
  );
  return winston.createLogger({
    level: logLevel,
    format: isProduction2 ? productionFormat : developmentFormat,
    transports: [
      new winston.transports.Console({
        handleExceptions: true,
        handleRejections: true
      })
    ],
    exitOnError: false
  });
};
var winstonLogger = createLogger();
